import {validateProject} from './model.js';
export function encodeWav(buffer,{bits=24,normalize=false,dither=bits===16}={}){
 const channels=buffer.numberOfChannels,frames=buffer.length,bytes=bits/8;if(![16,24].includes(bits))throw new Error('WAV bit depth must be 16 or 24.');const out=new ArrayBuffer(44+frames*channels*bytes),v=new DataView(out);const write=(s,o)=>{for(let i=0;i<s.length;i++)v.setUint8(o+i,s.charCodeAt(i));};write('RIFF',0);v.setUint32(4,out.byteLength-8,true);write('WAVEfmt ',8);v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,channels,true);v.setUint32(24,buffer.sampleRate,true);v.setUint32(28,buffer.sampleRate*channels*bytes,true);v.setUint16(32,channels*bytes,true);v.setUint16(34,bits,true);write('data',36);v.setUint32(40,frames*channels*bytes,true);
 const data=Array.from({length:channels},(_,i)=>buffer.getChannelData(i));let peak=0;for(const a of data)for(const s of a)if(Number.isFinite(s))peak=Math.max(peak,Math.abs(s));const gain=normalize&&peak>0?10**(-1/20)/peak:1;let clipped=0,offset=44,seed=9182;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)|0;return(seed>>>0)/4294967296;};
 for(let i=0;i<frames;i++)for(let c=0;c<channels;c++){let s=(Number.isFinite(data[c][i])?data[c][i]:0)*gain;if(Math.abs(s)>1)clipped++;if(dither)s+=(rand()-rand())/2**(bits-1);s=Math.max(-1,Math.min(1,s));const value=Math.round(s*(s<0?2**(bits-1):2**(bits-1)-1));if(bits===16)v.setInt16(offset,value,true);else{v.setUint8(offset,value&255);v.setUint8(offset+1,(value>>8)&255);v.setUint8(offset+2,(value>>16)&255);}offset+=bytes;}
 return {bytes:new Uint8Array(out),peak,clipped};
}
export function download(data,name,type='application/octet-stream'){const blob=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
export const safeName=s=>String(s).replace(/[^a-zA-Z0-9 _.-]/g,'').trim().slice(0,70)||'ASTRA';
export async function toBase64(blob){const bytes=new Uint8Array(await blob.arrayBuffer());let s='';for(let i=0;i<bytes.length;i+=32768)s+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(s);}
export function fromBase64(s){if(typeof s!=='string'||s.length>56_000_000)throw new Error('Invalid or oversized embedded sample.');const raw=atob(s);return Uint8Array.from(raw,c=>c.charCodeAt(0));}
export async function packProject(project,samples){const used=new Set(project.tracks.map(t=>t.sampleId).filter(Boolean));const assets=[];let total=0;for(const id of used){const s=samples.get(id);if(!s)throw new Error('A sample is missing. Replace it before saving.');total+=s.blob.size;if(total>64*1024*1024)throw new Error('Embedded samples exceed 64 MB. Use smaller audio files before saving.');assets.push({id,name:s.name,type:s.blob.type,data:await toBase64(s.blob)});}return JSON.stringify({format:'astra-studio',project,assets});}
export async function unpackProject(text,ctx){if(text.length>100_000_000)throw new Error('Project is larger than 100 MB.');const raw=JSON.parse(text);if(raw.format!=='astra-studio')throw new Error('Choose an ASTRA Studio .astra project.');const project=validateProject(raw.project);if(!Array.isArray(raw.assets)||raw.assets.length>16)throw new Error('Invalid embedded samples.');const samples=new Map();let total=0,decoded=0;for(const a of raw.assets){if(!a||typeof a.id!=='string'||samples.has(a.id))throw new Error('Invalid sample identifier.');const bytes=fromBase64(a.data);total+=bytes.length;if(total>64*1024*1024)throw new Error('Embedded audio exceeds 64 MB.');const buffer=await ctx.decodeAudioData(bytes.buffer.slice(0));if(buffer.duration>120)throw new Error('A sample exceeds two minutes.');decoded+=buffer.length*buffer.numberOfChannels*4;if(decoded>128*1024*1024)throw new Error('Decoded audio exceeds 128 MB.');samples.set(a.id,{name:String(a.name||'Sample').slice(0,120),blob:new Blob([bytes],{type:typeof a.type==='string'?a.type:'audio/wav'}),buffer});}for(const t of project.tracks)if(t.sampleId&&!samples.has(t.sampleId))throw new Error('Project is missing an embedded sample.');return {project,samples};}
function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('astra-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('sessions');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
export async function saveLocal(project,samples){const d=await db();try{await new Promise((resolve,reject)=>{const tx=d.transaction('sessions','readwrite');const used=new Set(project.tracks.map(t=>t.sampleId));tx.objectStore('sessions').put({project,assets:[...samples].filter(([id])=>used.has(id)).map(([id,s])=>({id,name:s.name,blob:s.blob})),saved:Date.now()},'recovery');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}finally{d.close();}}
export async function loadLocal(){const d=await db();try{return await new Promise((resolve,reject)=>{const r=d.transaction('sessions').objectStore('sessions').get('recovery');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}finally{d.close();}}
const crcTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
export const crc32=bytes=>{let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0;};
// Store-only ZIP avoids third-party code and preserves exact exported PCM bytes.
export function zip(files){const chunks=[],directory=[];let offset=0,centralSize=0;const encoder=new TextEncoder();for(const file of files){const name=encoder.encode(file.name),bytes=file.bytes,crc=crc32(bytes),header=new Uint8Array(30+name.length),h=new DataView(header.buffer);h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x800,true);h.setUint32(14,crc,true);h.setUint32(18,bytes.length,true);h.setUint32(22,bytes.length,true);h.setUint16(26,name.length,true);header.set(name,30);chunks.push(header,bytes);const c=new Uint8Array(46+name.length),v=new DataView(c.buffer);v.setUint32(0,0x02014b50,true);v.setUint16(4,20,true);v.setUint16(6,20,true);v.setUint16(8,0x800,true);v.setUint32(16,crc,true);v.setUint32(20,bytes.length,true);v.setUint32(24,bytes.length,true);v.setUint16(28,name.length,true);v.setUint32(42,offset,true);c.set(name,46);directory.push(c);centralSize+=c.length;offset+=header.length+bytes.length;}
 const end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,centralSize,true);e.setUint32(16,offset,true);return new Blob([...chunks,...directory,end],{type:'application/zip'});}
